shared_html.shared_css:
/* ============================================================
   Shared header + footer — Dīvān-i Shahr
   Persian Safavid, period_faithful
   ============================================================ */

.site-nav,
.site-footer {
  font-family: "EB Garamond", Georgia, serif;
  color: var(--text);
  background-color: var(--bg);
  position: relative;
}

/* ---- ornamental rules (cobalt + gold filet) ---- */
.site-nav__rule,
.site-footer__rule {
  height: 10px;
  background:
    linear-gradient(var(--bg), var(--bg)) padding-box,
    repeating-linear-gradient(
      90deg,
      var(--primary) 0 14px,
      var(--accent) 14px 16px,
      var(--primary) 16px 30px,
      var(--secondary) 30px 32px
    );
  border-top: 1px solid var(--accent);
  border-bottom: 1px solid var(--accent);
}
.site-nav__rule--bottom,
.site-footer__rule--bottom {
  margin-top: 0;
}

/* ============================================================
   HEADER
   ============================================================ */
.site-nav__inner {
  max-width: 1180px;
  margin: 0 auto;
  padding: 2.25rem 2rem 1.5rem;
  text-align: center;
}

.site-nav__brand {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 1.25rem;
}

.site-nav__seal {
  color: var(--accent);
  font-size: 1.35rem;
  letter-spacing: 0.4em;
  line-height: 1;
}

.site-nav__wordmark {
  display: inline-flex;
  flex-direction: column;
  align-items: center;
  text-decoration: none;
  color: var(--primary);
  line-height: 1.05;
}

.site-nav__wordmark-line1 {
  font-family: "Marcellus", "EB Garamond", serif;
  font-size: clamp(1.6rem, 2.6vw, 2.4rem);
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--primary);
}

.site-nav__wordmark-line2 {
  margin-top: 0.45rem;
  font-family: "EB Garamond", serif;
  font-style: italic;
  font-size: 0.95rem;
  letter-spacing: 0.14em;
  color: var(--text-emphasis);
  text-transform: none;
}

.site-nav__kicker {
  margin: 0.85rem 0 1.4rem;
  font-size: 0.78rem;
  letter-spacing: 0.32em;
  text-transform: uppercase;
  color: var(--secondary);
}

.site-nav__menu ul {
  list-style: none;
  margin: 0;
  padding: 0.55rem 0;
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 0;
  border-top: 1px solid var(--accent);
  border-bottom: 1px solid var(--accent);
}

.site-nav__menu li + li::before {
  content: "✶";
  color: var(--accent);
  margin: 0 0.9rem;
  font-size: 0.7rem;
  vertical-align: middle;
}

.site-nav__menu a {
  font-family: "Marcellus", serif;
  font-size: 0.92rem;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  text-decoration: none;
  color: var(--primary);
  padding: 0.35rem 0.4rem;
  transition: color 0.2s ease;
}

.site-nav__menu a:hover,
.site-nav__menu a:focus {
  color: var(--text-emphasis);
  outline: none;
}

/* ============================================================
   FOOTER
   ============================================================ */
.site-footer {
  margin-top: 4rem;
  background-color: var(--primary);
  color: var(--bg);
}

.site-footer .site-footer__rule {
  background:
    repeating-linear-gradient(
      90deg,
      var(--accent) 0 14px,
      var(--secondary) 14px 16px,
      var(--accent) 16px 30px,
      var(--bg) 30px 32px
    );
}

.site-footer__inner {
  max-width: 1180px;
  margin: 0 auto;
  padding: 3rem 2rem 2rem;
  text-align: center;
}

.site-footer__col--center {
  margin-bottom: 2.5rem;
}

.site-footer__seal {
  display: inline-block;
  color: var(--accent);
  font-size: 1.4rem;
  letter-spacing: 0.4em;
  margin-bottom: 0.6rem;
}

.site-footer__name {
  font-family: "Marcellus", serif;
  font-size: 1.6rem;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  margin: 0 0 0.5rem;
  color: var(--bg);
}

.site-footer__tagline {
  margin: 0;
  font-style: italic;
  font-size: 0.95rem;
  letter-spacing: 0.08em;
  color: var(--accent);
}

.site-footer__cols {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 2rem;
  text-align: left;
  margin-top: 1rem;
  padding-top: 2rem;
  border-top: 1px solid var(--accent);
}

.site-footer__col h4 {
  font-family: "Marcellus", serif;
  font-size: 0.78rem;
  letter-spacing: 0.28em;
  text-transform: uppercase;
  color: var(--accent);
  margin: 0 0 0.85rem;
  padding-bottom: 0.45rem;
  border-bottom: 1px solid var(--secondary);
}

.site-footer__col p {
  margin: 0;
  font-size: 0.95rem;
  line-height: 1.7;
  color: var(--bg);
}

.site-footer__nav {
  list-style: none;
  margin: 0;
  padding: 0;
}

.site-footer__nav li {
  margin: 0 0 0.35rem;
}

.site-footer__nav a {
  color: var(--bg);
  text-decoration: none;
  font-size: 0.95rem;
  letter-spacing: 0.04em;
  border-bottom: 1px dotted var(--secondary);
  transition: color 0.2s ease, border-color 0.2s ease;
}

.site-footer__nav a:hover,
.site-footer__nav a:focus {
  color: var(--accent);
  border-bottom-color: var(--accent);
  outline: none;
}

.site-footer__colophon {
  margin: 2.5rem 0 0;
  padding-top: 1.5rem;
  border-top: 1px solid var(--secondary);
  font-size: 0.85rem;
  font-style: italic;
  letter-spacing: 0.08em;
  color: var(--accent);
}

/* ============================================================
   Responsive
   ============================================================ */
@media (max-width: 880px) {
  .site-footer__cols {
    grid-template-columns: repeat(2, 1fr);
  }
  .site-nav__menu li + li::before {
    margin: 0 0.5rem;
  }
}

@media (max-width: 540px) {
  .site-nav__inner { padding: 1.75rem 1.25rem 1.25rem; }
  .site-nav__brand { flex-direction: column; gap: 0.5rem; }
  .site-nav__menu ul { flex-direction: column; padding: 0.75rem 0; }
  .site-nav__menu li + li::before { display: none; }
  .site-nav__menu a { display: block; padding: 0.45rem 0; }
  .site-footer__cols {
    grid-template-columns: 1fr;
    text-align: center;
  }
  .site-footer__col h4 {
    border-bottom: none;
  }
}
